package com.skyclone.mod.chocolate;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;

/**
 * The chocolate module's data, read from {@code data/chocolate/*.json} (generated by
 * {@code tools/gen/chocolate/gen_chocolate.py} from NEU {@code hoppity.json} and SkyHanni's
 * {@code HoppityEggLocations.json} / {@code HoppityRabbitTextures.json}). Pure: takes a resource opener, so unit
 * tests read the very same files the server does.
 */
public final class ChocCatalog {

    /** One collectible Chocolate Rabbit. */
    public static final class Rabbit {
        public String id;
        public String name;
        public String ref;
        public String rarity;
        public double cps;
        public double mult;
        /** egg | factory_milestone | shop_milestone | stray */
        public String source;
        public String texture;
        /** The amount of chocolate (factory) or chocolate spent (shop) that awards it. */
        public double milestone;
        /** Residents: only found in eggs on these islands. Null = anywhere. */
        public List<String> islands;
        /** Mythic perk key (see {@link ChocMath}) and its number. */
        public String ability;
        public double abilityValue;
        public String abilityText;

        public boolean resident() { return islands != null && !islands.isEmpty(); }
        public boolean fromEggs() { return "egg".equals(source); }
        public int rarityRank() { return ChocMath.rarityRank(rarity); }
    }

    public static final class Employee {
        public String id;
        public String name;
        public int cps;
        public double baseCost;
        public int prestige;
        /** Rabbit Youth (hunting attribute) raises this employee's level cap. */
        public boolean youth;
    }

    public static final class Prestige {
        public int level;
        public double requirement;
        public double bonus;
    }

    /** One upgrade line (barn, Time Tower, shrine, coach, hand-baked). Fields unused by a line stay 0. */
    public static final class Upgrade {
        public int prestige;
        public int max;
        public double perLevel;
        public int charges;
        public double chargeHours;
        public int minutes;
        public double baseCost;
        public double growth;
        public int start;
        public double costPerLevel;
    }

    public static final class Milestone {
        public double amount;
        public String rabbit;
    }

    public static final class Meal {
        public String id;
        public String name;
        public int hour;
        public String color;
        public boolean side;
    }

    public static final class Talisman {
        public String item;
        public double cps;
        public double unique;
        public int prestige;
        public double cost;
    }

    public static final class ShopEntry {
        public String item;
        public double cost;
        public int prestige = 1;
        /** A rabbit id that must be in the collection first. */
        public String requires;
        /** Item owned by a module that may not exist yet: skipped (not an error) when missing. */
        public boolean optional;
        public boolean talisman;
    }

    public static final class Factory {
        public List<Employee> employees = new ArrayList<>();
        public double employeeGrowth;
        public int levelCapBase;
        public int levelCapPerPrestige;
        public List<Prestige> prestiges = new ArrayList<>();
        public Upgrade handBaked;
        public Upgrade barn;
        public Upgrade timeTower;
        public Upgrade shrine;
        public Upgrade coach;
        public List<Double> hitmanCosts = new ArrayList<>();
        public List<Milestone> factoryMilestones = new ArrayList<>();
        public List<Milestone> shopMilestones = new ArrayList<>();
        public List<Meal> meals = new ArrayList<>();
        public Map<String, Integer> eggOdds = new LinkedHashMap<>();
        public Map<String, Double> duplicateSeconds = new HashMap<>();
        public Map<String, Double> duplicateFloor = new HashMap<>();
        public List<Talisman> talismans = new ArrayList<>();
        public Map<String, Integer> skyXp = new HashMap<>();
        public List<String> factionRabbits = new ArrayList<>();
        /** Hopsworth's skin texture (NEU HOPPITY_NPC). */
        public String npcSkin;
    }

    public final List<Rabbit> rabbits;
    public final Map<String, Rabbit> byId;
    public final Factory factory;
    public final List<ShopEntry> shop;

    private ChocCatalog(List<Rabbit> rabbits, Factory factory, List<ShopEntry> shop) {
        this.rabbits = Collections.unmodifiableList(rabbits);
        Map<String, Rabbit> m = new LinkedHashMap<>();
        for (Rabbit r : rabbits) m.put(r.id, r);
        this.byId = Collections.unmodifiableMap(m);
        this.factory = factory;
        this.shop = Collections.unmodifiableList(shop);
    }

    public static ChocCatalog load(Function<String, InputStream> open) {
        Gson g = new Gson();
        List<Rabbit> rabbits = read(g, open, "rabbits.json", new TypeToken<List<Rabbit>>() {});
        Factory f = read(g, open, "factory.json", new TypeToken<Factory>() {});
        List<ShopEntry> shop = read(g, open, "shop.json", new TypeToken<List<ShopEntry>>() {});
        for (Rabbit r : rabbits) r.rarity = r.rarity == null ? "COMMON" : r.rarity.toUpperCase(Locale.ROOT);
        return new ChocCatalog(rabbits, f, shop);
    }

    private static <T> T read(Gson g, Function<String, InputStream> open, String file, TypeToken<T> type) {
        InputStream in = open.apply(file);
        if (in == null) throw new IllegalStateException("missing data/chocolate/" + file);
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            T t = g.fromJson(r, type.getType());
            if (t == null) throw new IllegalStateException("empty data/chocolate/" + file);
            return t;
        } catch (java.io.IOException e) {
            throw new IllegalStateException("cannot read data/chocolate/" + file, e);
        }
    }

    public Rabbit rabbit(String id) { return id == null ? null : byId.get(id.toLowerCase(Locale.ROOT)); }

    public Employee employee(String id) {
        for (Employee e : factory.employees) if (e.id.equals(id)) return e;
        return null;
    }

    public Meal meal(String id) {
        for (Meal m : factory.meals) if (m.id.equals(id)) return m;
        return null;
    }

    public Prestige prestige(int level) {
        for (Prestige p : factory.prestiges) if (p.level == level) return p;
        return null;
    }

    public int maxPrestige() {
        int m = 1;
        for (Prestige p : factory.prestiges) m = Math.max(m, p.level);
        return m;
    }

    /** Rabbits of one rarity, in file order. */
    public List<Rabbit> ofRarity(String rarity) {
        List<Rabbit> out = new ArrayList<>();
        for (Rabbit r : rabbits) if (r.rarity.equals(rarity)) out.add(r);
        return out;
    }

    /** Residents of an island (rabbits only found in that island's eggs). */
    public List<Rabbit> residents(String island) {
        List<Rabbit> out = new ArrayList<>();
        for (Rabbit r : rabbits) if (r.resident() && r.islands.contains(island)) out.add(r);
        return out;
    }

    public Talisman talisman(String item) {
        for (Talisman t : factory.talismans) if (t.item.equals(item)) return t;
        return null;
    }
}
